"""Evidence synthesis of eligibility and cohort mixture; no algorithm selection."""
from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[2];H=R/'research/round119';O=H/'analysis_attempt001';rd=lambda p:json.loads(Path(p).read_text())
def main():
 assert rd(H/'INDEPENDENT_AUDIT.json')['n']==18620;assert rd(H/'POSTSTRATIFICATION_AUDIT.json')['method_rows']==450;agg=rd(O/'AGGREGATE_ROWS.json');m=rd(O/'METHOD_ROWS.json');comp=rd(O/'COMPOSITION_ROWS.json');re=rd(O/'R118_POSTSTRATIFIED_AGGREGATE_ROWS.json');rows=[r for p in O.glob('*_ALL_ROWS_PRIVATE.json') for r in rd(p)];total={}
 for t in [25,50]:
  no=sum(r['oracle_IoU']<=t/100 for r in rows);rank=sum(r['oracle_IoU']>t/100 and r['values']['original_source']<=t/100 for r in rows);total[str(t)]={'source_failures':no+rank,'no_good_candidate':no,'covered_but_not_selected':rank,'pooled_recoverable_fraction':rank/(no+rank)}
 cs=[]
 for co in ['DEV','EXP']:
  cc=[x for x in comp if x['cohort']==co and x['arm']=='original_source'];a={k:float(np.mean([r[k] for r in cc])) for k in ['difference_pp','scene_mixture_component_pp','within_scene_component_pp']};cs.append({'cohort':co,**a,'fraction_of_signed_gap_in_scene_mixture':a['scene_mixture_component_pp']/a['difference_pp']})
 summary={'n':18620,'paired_directed_inputs_not_independent_physical_instances':True,'threshold_counts':total,'source_score_cohort_shift':cs,'new_GT_scoring':0,'new_model_or_features':0,'TTA_adoption':False,'FINAL_access':False};(H/'SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n')
 lines=['# R119 — 六方向全量候选覆盖、排序空间与开发集场景构成','','本轮是已经封存结果的事后诊断，不是新TTA，不生成标签或修改模型。全部18620定向输入、原A256、8固定历史读出全部保留。只读取R100保存的候选oracle/任务标量与已有清单；没有新模型、媒体、特征、标注或GT几何评分。2304条R118的原始source任务值与R100逐条精确一致，排除了当前两组高分来自不同source权重/点采样/读出版本的解释。','','## 固定框下还能改善多少','','oracle只表示使用GT从既有A256中选框的上限，不是部署选择器，也不提供实例身份真值。严格IoU>.25/.5与原评估一致。以下主汇总六方向等权，Waymo较多样本不额外加权。','','| 范围 | 原source mIoU% | 固定候选oracle mIoU% | Acc25% | oracle Acc25% | Acc50% | oracle Acc50% |','|---|---:|---:|---:|---:|---:|---:|']
 for co in ['FULL','DEV','EXP','REMAINDER']:
  x=next(x for x in agg if x['cohort']==co and x['group']=='all_six_equal' and x['arm']=='original_source');lines.append(f"| {co} | {x['mIoU_percent']:.6f} | {x['oracle_mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['oracle_Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} | {x['oracle_Acc50_percent']:.6f} |")
 lines+=['','全量source为11.754125%，固定候选oracle为34.575322%，仍有22.821197pp的GT选择上限差距。Acc25由22.475706%到79.375913%有大量排序空间，不能将主失败归结为“候选池没有好框”。但Acc50的固定池上限只有18.687416%，所以当前只改排序的路线不可能解决多数严格几何失败。两个阈值的研究边界不同。','','| 方向 | n | source mIoU% | oracle mIoU% | 无25好框 | 有25好框却未选中 | 失败中可恢复比例 | oracle Acc50% |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for x in m:
  if x['cohort']=='FULL' and x['arm']=='original_source':lines.append(f"| {x['source']}→{x['target']} | {x['n']} | {x['mIoU_percent']:.6f} | {x['oracle_mIoU_percent']:.6f} | {x['no_good_candidate_at25']} | {x['covered_but_not_selected_at25']} | {100*x['fraction_of_failures_recoverable_at25']:.3f}% | {x['oracle_Acc50_percent']:.3f} |")
 lines+=['','合并18620行的精确计数与按六方向等权比例应分开：','','```json',json.dumps(total,indent=2),'```','','这些可恢复样本仅用于解释，不会筛入适应集合、伪标签或接受规则；没有好框和UNKNOWN仍保留总分分母。','','## 开发数据为何显著高分','','DEV768=384表达×2source；EXP1536=768表达×2source；REMAINDER16316。它们都是历史曝光数据，分开不是创建独立测试集。开发/扩展清单按场景平衡，完整VAL各场景表达数量不平衡。利用完整集每个场景均值，按开发场景占比重加权，作下面的纯算术分解：','','`cohort-full = (reweighted full scene means-full mean) + (cohort mean-reweighted full scene means)`','','第一项反映场景混合差异，第二项包含同场景样本选择差异；不称因果归因，也不保证各场景内随机代表性。','','```json',json.dumps(cs,indent=2),'```','','Waymo→Quad：source DEV33.347552%，全量17.588082%，相差15.759470pp；其中场景占比项11.525885pp、场景内项4.233585pp。Waymo→Drone对应8.024174pp差异中，占比项6.358030pp。高分开发场景不代表全量同权总体的主要样本。不同采样分数不能直接纵向当算法进步。','','## 固定历史TTA在不同范围的表现','','| 范围 | 方法 | mIoU% | Acc25% | Acc50% |','|---|---|---:|---:|---:|']
 for x in agg:
  if x['group']=='all_six_equal':lines.append(f"| {x['cohort']} | {x['arm']} | {x['mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} |")
 lines+=['','所有prepared/source、TTA/直接使用、TTA/错配的改善/损伤计数与源模型原来已正确的恢复拆分均在PAIRED_ROWS公开。最大单例对主六方向均值的贡献按100/(6×该方向n)计算，不能用100/18620替代。没有把阈值变化当作真实实例身份认证；未重看原图的尾部案例一律UNKNOWN。','','## 已封存R118的场景后分层核对','','权重仅由全量场景行数决定，对25个方法完全相同，不读取IoU选择权重。DEV与DEV+EXP并集覆盖所有93个Waymo/2个Drone/3个Quad场景；EXP只覆盖89/93个Waymo场景，故其对应行标记共同支持范围，不能冒充完整集估计。缺失场景没有填均值。即使覆盖完整，场景内样本仍可能有偏，所以以下不是实际全量新推理或独立确认。','','| 范围 | 方法 | 覆盖全量质量的最小值 | 场景后分层 mIoU% |','|---|---|---:|---:|']
 for x in re:
  if x['group']=='all_six_equal' and x['arm'] in ['original_source','prepared_A','prepared_F','native_F','repaired_F','lateOnly_F','F_lSA_rSA','F_lSA_rSF','F_lSAshuffled_rSAshuffled','ABC_lSA_rSA','ABC_native']:lines.append(f"| {x['cohort']} | {x['arm']} | {x['min_covered_full_mass']:.6f} | {x['mIoU_percent']:.6f} |")
 lines+=['','这一步不会推翻R118预注册裁决或更换主项。DEV主项原17.354112%的尺度，在相同数据按完整场景比例后为12.677064%；source由16.811383%变12.186315%。相对方法差异仍需逐个比较，不能把绝对降分归因于代码或泛化失败。EXP主项后分层12.823489%，仍低于lateOnly12.880574%，因此也没有获得稳健采用证据。','','## 对下一步的约束','','1. 现有A256在Acc25仍有明显排序空间，研究实例匹配/更新信号仍有任务资格；Acc50应同时报告几何上限，不承诺仅匹配TTA能解决几何。','2. 后续有限开发比较必须同时报原清单均值、全量场景占比后分层与各方向/各场景；最终收益仍需实际完整资格集测量，后分层不能取代它。','3. 不依据这份GT诊断按场景拼参数、过滤伪标签或选择最有利权重；不通过增加更易场景样本来制造总体涨分。','4. R85已测试解除锚点保护且未带来任务增量，R77/R78已测试接口能力/源域方向/元辅助准备；不将这些旧失败包装成未探索新路径。','5. 现有证据仍未建立稳定优于同信息直接使用与错配控制的TTA。R118的SF残差/SA late只是开发次项，不因这次重加权自动升级。','','## 完整性','','18620旧行逐条与原保存值核验；2304跨轮source值精确一致；所有范围/阈值拆分、成对变化、场景分解和后分层由独立代码重算。所有负例和缺证据均保留，FINAL未访问；没有把同一表达两个source当独立物理实例，也不基于Drone2/Quad3场景输出总体跨场景CI。'];(H/'REPORT.md').write_text('\n'.join(lines)+'\n');print('REPORT119_COMPLETE',json.dumps(summary),flush=True)
if __name__=='__main__':main()
